1325	/// Merges slices `left` and `right` in parallel and stores the result into `dest`.
1326	///
1327	/// # Safety
1328	///
1329	/// The `dest` pointer must have enough space to store the result.
1330	///
1331	/// Even if `is_less` panics at any point during the merge process, this function will fully copy
1332	/// all elements from `left` and `right` into `dest` (not necessarily in sorted order).
1333	unsafe fn par_merge<T, F>(left: &mut [T], right: &mut [T], dest: *mut T, is_less: &F)
1334	where
1335	    T: Send,
1336	    F: Fn(&T, &T) -> bool + Sync,
1337	{
1338	    unsafe {
1339	        // Slices whose lengths sum up to this value are merged sequentially. This number is slightly
1340	        // larger than `CHUNK_LENGTH`, and the reason is that merging is faster than merge sorting, so
1341	        // merging needs a bit coarser granularity in order to hide the overhead of Rayon's task
1342	        // scheduling.
1343	        const MAX_SEQUENTIAL: usize = 5000;
1344	
1345	        let left_len = left.len();
1346	        let right_len = right.len();
1347	
1348	        // Intermediate state of the merge process, which serves two purposes:
1349	        // 1. Protects integrity of `dest` from panics in `is_less`.
1350	        // 2. Copies the remaining elements as soon as one of the two sides is exhausted.
1351	        //
1352	        // Panic safety:
1353	        //
1354	        // If `is_less` panics at any point during the merge process, `s` will get dropped and copy the
1355	        // remaining parts of `left` and `right` into `dest`.
1356	        let mut s = State {
1357	            left_start: left.as_mut_ptr(),
1358	            left_end: left.as_mut_ptr().add(left_len),
1359	            right_start: right.as_mut_ptr(),
1360	            right_end: right.as_mut_ptr().add(right_len),
1361	            dest,
1362	        };
1363	
1364	        if left_len == 0 || right_len == 0 || left_len + right_len < MAX_SEQUENTIAL {
1365	            while s.left_start < s.left_end && s.right_start < s.right_end {
1366	                // Consume the lesser side.
1367	                // If equal, prefer the left run to maintain stability.
1368	                let is_l = is_less(&*s.right_start, &*s.left_start);
1369	                let to_copy = if is_l { s.right_start } else { s.left_start };
1370	                ptr::copy_nonoverlapping(to_copy, s.dest, 1);
1371	                s.dest = s.dest.add(1);
1372	                s.right_start = s.right_start.add(is_l as usize);
1373	                s.left_start = s.left_start.add(!is_l as usize);
1374	            }
1375	        } else {
1376	            // Function `split_for_merge` might panic. If that happens, `s` will get destructed and copy
1377	            // the whole `left` and `right` into `dest`.
1378	            let (left_mid, right_mid) = split_for_merge(left, right, is_less);
1379	            let (left_l, left_r) = left.split_at_mut(left_mid);
1380	            let (right_l, right_r) = right.split_at_mut(right_mid);
1381	
1382	            // Prevent the destructor of `s` from running. Rayon will ensure that both calls to
1383	            // `par_merge` happen. If one of the two calls panics, they will ensure that elements still
1384	            // get copied into `dest_left` and `dest_right``.
1385	            mem::forget(s);
1386	
1387	            // Wrap pointers in SendPtr so that they can be sent to another thread
1388	            // See the documentation of SendPtr for a full explanation
1389	            let dest_l = SendPtr(dest);
1390	            let dest_r = SendPtr(dest.add(left_l.len() + right_l.len()));
1391	            rayon_core::join(
1392	                move || par_merge(left_l, right_l, dest_l.get(), is_less),
1393	                move || par_merge(left_r, right_r, dest_r.get(), is_less),
1394	            );
1395	        }
1396	        // Finally, `s` gets dropped if we used sequential merge, thus copying the remaining elements
1397	        // all at once.
1398	
1399	        // When dropped, copies arrays `left_start..left_end` and `right_start..right_end` into `dest`,
1400	        // in that order.
1401	        struct State<T> {
1402	            left_start: *mut T,
1403	            left_end: *mut T,
1404	            right_start: *mut T,
1405	            right_end: *mut T,
1406	            dest: *mut T,
1407	        }
1408	
1409	        impl<T> Drop for State<T> {
1410	            fn drop(&mut self) {
1411	                // Copy array `left`, followed by `right`.
1412	                unsafe {
1413	                    let left_len = self.left_end.offset_from(self.left_start) as usize;
1414	                    ptr::copy_nonoverlapping(self.left_start, self.dest, left_len);
1415	                    self.dest = self.dest.add(left_len);
1416	
1417	                    let right_len = self.right_end.offset_from(self.right_start) as usize;
1418	                    ptr::copy_nonoverlapping(self.right_start, self.dest, right_len);
1419	                }
1420	            }
1421	        }
1422	    }
